def solve(grid, start, goal):
    from collections import deque

    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbors(row, col):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        return [(row + dr, col + dc) for dr, dc in directions if is_valid(row + dr, col + dc)]

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(start[0], start[1], [start])])
    visited[start[0]][start[1]] = True

    while queue:
        row, col, path = queue.popleft()
        if (row, col) == goal:
            return path
        for neighbor_row, neighbor_col in get_neighbors(row, col):
            if not visited[neighbor_row][neighbor_col]:
                visited[neighbor_row][neighbor_col] = True
                new_path = path + [(neighbor_row, neighbor_col)]
                queue.append((neighbor_row, neighbor_col, new_path))

    return []
